local facadeSource = nil

local module = {}

local playerFacades = {}

local rootFacade = nil

local rootServices = nil

local createFacadeWithServices = function(services: ServiceProvider): TangSengFacade
	assert(facadeSource, "FacadeSource is not set")
	local moduleScript = facadeSource:Clone()
	local facade = require(moduleScript)
	facade.__Services = services
	task.spawn(function()
		moduleScript:Destroy()
	end)
	return facade
end

module.__SetFacadeSource = function(source: ModuleScript)
	facadeSource = source
end

module.GetFacadeOfPlayer = function(playerOrUserId: Player | number): TangSengFacade
	assert(playerOrUserId)
	if not typeof(playerOrUserId) == "number" then
		playerOrUserId = playerOrUserId.UserId
	end
	local facade = playerFacades[playerOrUserId]

	if not facade then
		local root = module.GetRootFacade()
		local scopeService = root.getIPlayerScopeService()
		local playerScope = scopeService.GetPlayerScope(playerOrUserId)
		if not playerScope then
			return nil
		end
		facade = createFacadeWithServices(playerScope)
		playerFacades[playerOrUserId] = facade
	end

	return facade
end

module.GetRootFacade = function()
	assert(rootFacade)
	return rootFacade
end

module.GetPlayerScope = function(playerOrUserId: Player | number): IServiceScope
	assert(playerOrUserId)
	if not typeof(playerOrUserId) == "number" then
		playerOrUserId = playerOrUserId.UserId
	end
	local scopeService = module.GetServices():GetRequiredService("IPlayerScopeService")
	local playerScope = scopeService.GetPlayerScope(playerOrUserId)
	if not playerScope then
		return nil
	end
    return playerScope
end


module.GetServices = function()
	assert(rootServices)
	return rootServices
end

module.__SetRootFacadeServices = function(services: ServiceProvider)
	assert(not rootFacade, "RootFacade is already set")
	local facade = createFacadeWithServices(services)
	rootFacade = facade
	rootServices = services
end

module.__innerDispose = function()
	rootFacade = nil
	playerFacades = {}
end

game.Players.PlayerRemoving:Connect(function(player: Player)
	playerFacades[player.UserId] = nil
end)

return module
